// FILE: frontend/src/LogDetail.js
//
// --- VERSION 1.1.0 CHANGE ---
// - FIXED: Chart colors were too similar. Changed Engine RPM to a high-contrast
//   amber/orange color for much better readability.
// -----------------------------

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

function LogDetail() {
  const { logId } = useParams();
  const [chartData, setChartData] = useState(null);
  const [status, setStatus] = useState('Loading log data...');
  const [logFileName, setLogFileName] = useState('');


  useEffect(() => {
	const fetchLogData = async () => {
	  try {
		// First, get the log details to display the filename
		const logInfoResponse = await axios.get('http://localhost:5001/api/logs');
		const currentLog = logInfoResponse.data.find(log => log.log_id === parseInt(logId));
		if (currentLog) {
			setLogFileName(currentLog.file_name);
		}

		// Now fetch the chart data
		const response = await axios.get(`http://localhost:5001/api/logs/${logId}/data`);
		const { data, columns } = response.data;

		const speedCol = columns.find(c => c.includes('vehicle_speed'));
		const rpmCol = columns.find(c => c.includes('engine_rpm'));

		if (!speedCol || !rpmCol) {
			setStatus('This log does not contain required speed or RPM data for charting.');
			return;
		}

		const labels = data.map(row => new Date(row.timestamp * 1000).toLocaleTimeString());

		setChartData({
		  labels,
		  datasets: [
			{
			  label: 'Vehicle Speed (MPH)',
			  data: data.map(row => row[speedCol]),
			  borderColor: 'rgb(56, 189, 248)', // sky-400
			  backgroundColor: 'rgba(56, 189, 248, 0.5)',
			  yAxisID: 'y',
			},
			{
			  label: 'Engine RPM',
			  data: data.map(row => row[rpmCol]),
			  // **FIX:** Changed to a high-contrast amber color
			  borderColor: 'rgb(245, 158, 11)', // amber-500
			  backgroundColor: 'rgba(245, 158, 11, 0.5)',
			  yAxisID: 'y1',
			},
		  ],
		});
	  } catch (error) {
		console.error("Error fetching log detail:", error);
		setStatus('Failed to load log data.');
	  }
	};

	fetchLogData();
  }, [logId]);

  const options = {
	responsive: true,
	interaction: {
	  mode: 'index',
	  intersect: false,
	},
	plugins: {
	  title: {
		display: true,
		text: `Trip Data for: ${logFileName}`,
		color: '#FFFFFF',
		font: { size: 18 }
	  },
	  legend: {
		labels: { color: '#FFFFFF' }
	  }
	},
	scales: {
	  x: {
		ticks: { color: '#9CA3AF' } // gray-400
	  },
	  y: {
		type: 'linear',
		display: true,
		position: 'left',
		title: {
		  display: true,
		  text: 'Speed (MPH)',
		  color: 'rgb(56, 189, 248)'
		},
		ticks: { color: 'rgb(56, 189, 248)' }
	  },
	  y1: {
		type: 'linear',
		display: true,
		position: 'right',
		title: {
		  display: true,
		  text: 'Engine RPM',
		  color: 'rgb(245, 158, 11)' // amber-500
		},
		ticks: { color: 'rgb(245, 158, 11)' },
		grid: {
		  drawOnChartArea: false,
		},
	  },
	},
  };

  return (
	<div className="bg-gray-800 rounded-lg shadow-xl p-4">
	  {chartData ? (
		<Line options={options} data={chartData} />
	  ) : (
		<p className="text-center text-gray-400 py-8">{status}</p>
	  )}
	</div>
  );
}

export default LogDetail;
